import{_ as a,o as e,c as n,a5 as o}from"./chunks/framework.BF53ZjCA.js";const p=JSON.parse('{"title":"Cutting","description":"","frontmatter":{"title":"Cutting"},"headers":[],"relativePath":"cutting/intro.md","filePath":"cutting/intro.md","lastUpdated":1789155237000}'),r={name:"cutting/intro.md"};function i(c,t,s,d,l,h){return e(),n("div",null,[...t[0]||(t[0]=[o('<h1 id="cutting" tabindex="-1">Cutting <a class="header-anchor" href="#cutting" aria-label="Permalink to &quot;Cutting&quot;">​</a></h1><p>Cutting transforms rough into a gem. This module covers three main routes — faceting, cabochon &amp; carving, and the history and parameters of fancy cuts. The choice also depends on transparency, inclusions, durability, phenomena, and the shape of the rough.</p><h2 id="cutting-topics" tabindex="-1">Cutting Topics <a class="header-anchor" href="#cutting-topics" aria-label="Permalink to &quot;Cutting Topics&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Topic</th><th>Summary</th></tr></thead><tbody><tr><td><a href="./rough-planning.html">Rough Planning &amp; Orientation</a></td><td>Cutting does not begin with choosing an attractive outline. The cutter first reads the rough: color zoning, fractures, inclusions, transparency, crystallographic direction, and possible optical phenomena. A plan balances weight retention, appearance, and durability, recording the table orientation, target outline, risks, and acceptable loss.</td></tr><tr><td><a href="./brilliant-cut.html">Round Brilliant Cut</a></td><td>The classic diamond cut — standard 57–58 facets, formalised by Marcel Tolkowsky&#39;s 1919 proportion theory. Table, crown, girdle, and pavilion proportions maximise internal reflection and fire.</td></tr><tr><td><a href="./fancy-cuts.html">Fancy Cuts</a></td><td>Every non-round shape is a fancy cut — princess, emerald, pear, oval, marquise, heart, and the emerald step cut among others. Choice follows rough shape, inclusion placement, and aesthetic taste.</td></tr><tr><td><a href="./cabochon-and-carving.html">Cabochon &amp; Carving</a></td><td>When transparency, inclusions, durability, or an optical phenomenon favors a dome, a stone may be polished en cabochon or carved. This is not an absolute ban on faceting. Cabochons can reveal asterism, chatoyancy, and adularescence; jade and agate are also often carved.</td></tr></tbody></table>',4)])])}const g=a(r,[["render",i]]);export{p as __pageData,g as default};
